  except ValueError:
    raise argparse.ArgumentTypeError(
        f'Invalid date: {value!r}. Expected format YYYY-MM-DD.')


def _parse_args(args):
  """Parse command-line arguments for the cron job."""
  parser = argparse.ArgumentParser(
      description='Aggregate the previous day\'s fuzzer stats into BigQuery.')
  parser.add_argument(
      '--non-dry-run',
      action='store_true',
      help='If set, perform write operations. Otherwise, only log actions.')
  parser.add_argument(
