      '  SUM(testcases_executed) AS testcases_executed,\n'
      '  SUM(testcase_execution_duration) AS testcase_execution_duration,\n'
      '  SUM(testcases_generated) AS testcases_generated,\n'
      '  SUM(testcase_generation_duration) AS testcase_generation_duration,\n'
      '  SUM(fuzzing_duration) AS fuzzing_duration\n'
      f'FROM `{DATASET_ID}.TestcaseRun`\n'
      "WHERE DATE(TIMESTAMP_SECONDS(CAST(timestamp AS INT64))) = "
      f"'{date_string}'\n"
      'GROUP BY fuzzer_name')


